// Ambient types for the virtual modules generated by @pleatkit/vite-plugin.
// Add `"types": ["@pleatkit/vite-plugin/client"]` to the app tsconfig.

declare module 'virtual:pleatkit/manifest' {
  interface ManifestFile {
    path: string
    source: string
  }
  const manifest: {
    version: 1
    dynamicRoots: string[]
    dynamic: ManifestFile[]
    readonly: ManifestFile[]
    coreTypes: ManifestFile[]
    externals: string[]
    externalPatterns: string[]
    alias: Record<string, string>
    css?: { mode: 'tailwind' | 'palette'; input?: string; hash: string }
  }
  export default manifest
}

declare module 'virtual:pleatkit/externals' {
  const externals: Record<string, Record<string, unknown> | (() => Promise<Record<string, unknown>>)>
  export default externals
}

declare module 'virtual:pleatkit/fallback' {
  const fallback: Record<string, Record<string, unknown>>
  export default fallback
}

declare module 'virtual:pleatkit/wasm-url' {
  const wasmURL: string | null
  export default wasmURL
}

declare module 'virtual:pleatkit/tailwind' {
  export function compile(
    css: string,
    options: {
      base?: string
      loadStylesheet?: (id: string, base: string) => Promise<{ path: string; base: string; content: string }>
      loadModule?: (id: string, base: string, resourceHint: 'plugin' | 'config') => Promise<never>
    },
  ): Promise<{ build(candidates: string[]): string }>
  export const input: string
  export const stylesheets: Record<string, string>
  export const extraSources: string[]
}

declare module 'virtual:pleatkit/css' {
  const css: { mode: 'tailwind' | 'palette'; load: (() => Promise<typeof import('virtual:pleatkit/tailwind')>) | null }
  export default css
}

declare module 'virtual:pleatkit/isolated' {
  /** URL of the iframe host script (served with Access-Control-Allow-Origin: *). */
  const isolated: { url: string } | null
  export default isolated
}

declare module 'virtual:pleatkit' {
  export { default as manifest } from 'virtual:pleatkit/manifest'
  export { default as externals } from 'virtual:pleatkit/externals'
  export { default as fallback } from 'virtual:pleatkit/fallback'
  export { default as wasmURL } from 'virtual:pleatkit/wasm-url'
  export { default as css } from 'virtual:pleatkit/css'
  export { default as isolated } from 'virtual:pleatkit/isolated'
  /** Where edits are compiled: `server` (default) or `browser`. */
  export const compile: 'server' | 'browser'
  /** Public key bundles must be signed with, or null. */
  export const publicKey: string | null
  /** `vite serve`: edits compiled in the browser keep an inline source map. */
  export const dev: boolean
  /** Every edited panel runs in the sandboxed iframe. */
  export const isolateEdits: boolean
  /** The visible text of a pointed panel goes to the agent (default false: structure only). */
  export const sendDomText: boolean
}

// Pre-rename ids (DECISIONS 68): the plugin resolves `virtual:morphkit/...` to `virtual:pleatkit/...` for one release.
declare module 'virtual:morphkit' {
  export * from 'virtual:pleatkit'
}
declare module 'virtual:morphkit/manifest' {
  export { default } from 'virtual:pleatkit/manifest'
}
declare module 'virtual:morphkit/externals' {
  export { default } from 'virtual:pleatkit/externals'
}
declare module 'virtual:morphkit/fallback' {
  export { default } from 'virtual:pleatkit/fallback'
}
declare module 'virtual:morphkit/wasm-url' {
  export { default } from 'virtual:pleatkit/wasm-url'
}
declare module 'virtual:morphkit/css' {
  export { default } from 'virtual:pleatkit/css'
}
declare module 'virtual:morphkit/tailwind' {
  export * from 'virtual:pleatkit/tailwind'
}
declare module 'virtual:morphkit/isolated' {
  export { default } from 'virtual:pleatkit/isolated'
}
